 tabs.onkeydown=e=>{const ids=tools.map(t=>t[0]),i=ids.indexOf(current);const n=e.key==='ArrowRight'?(i+1)%ids.length:e.key==='ArrowLeft'?(i+ids.length-1)%ids.length:-1;if(n>=0){e.preventDefault();show(ids[n],true)}};
